namespace LeoLauncher;
sealed class MediaForm:BarcaWindow
{
    readonly ComboBox sources=new(){DropDownStyle=ComboBoxStyle.DropDownList};readonly Label title=new(),detail=new(),status=new();readonly CancellationTokenSource life=new();readonly System.Windows.Forms.Timer timer=new(){Interval=5000};readonly Func<string,string,CancellationToken,Task<string>> action;readonly bool preview;bool refreshing,busy,closed;
    public MediaForm(Func<string,string,CancellationToken,Task<string>> execute,bool demo=false)
    {
        action=execute;preview=demo;Text="Leo · 媒体控制";ClientSize=new(600,435);StartPosition=FormStartPosition.CenterScreen;BackColor=BarcaUi.Canvas;ForeColor=BarcaUi.Text;Font=BarcaUi.Font();var chrome=BarcaUi.Chrome(this,"媒体控制","选择播放器，再直接控制；点歌仍由QQ音乐负责。");
        sources.Bounds=new(24,110,552,33);CompanionUi.ThemeCombo(sources);sources.SelectedIndexChanged+=(_,_)=>{if(sources.SelectedItem is MediaSession item){MediaControl.Service.SelectedId=item.Id;title.Text=item.Title;detail.Text=item.Provider+" · "+(item.Status switch{"Playing"=>"播放中","Paused"=>"已暂停","Stopped"=>"已停止","Opened"=>"已打开","Closed"=>"已关闭","Changing"=>"正在切换",_=>"播放器未提供播放状态"})+"\n"+item.Artist;}};
        title.SetBounds(24,163,552,57);title.Font=BarcaUi.Font(16,true);title.AutoEllipsis=true;detail.SetBounds(24,225,552,48);detail.ForeColor=BarcaUi.Muted;
        var buttons=new FlowLayoutPanel{Bounds=new(24,287,552,40),WrapContents=false};foreach(var (label,command) in new[]{("上一项","previous"),("播放 / 暂停","toggle"),("下一项","next"),("停止","stop")}){var button=new BarcaButton{Text=label,Width=command=="toggle"?150:115,Height=34};button.Click+=async(_,_)=>{if(busy)return;try{busy=true;button.Enabled=false;var selected=sources.SelectedItem as MediaSession??throw new ArgumentException("请先选择播放器");status.Text=await action("media_"+command,selected.Id,life.Token);await RefreshSources();}catch(OperationCanceledException){}catch(Exception e){if(!IsDisposed)status.Text=e.Message;}finally{busy=false;if(!button.IsDisposed)button.Enabled=true;}};buttons.Controls.Add(button);}
        var open=new BarcaButton{Text="打开PotPlayer",Bounds=new(24,342,160,32)};open.Click+=async(_,_)=>{try{if(!preview)MediaControl.OpenPotPlayer();status.Text="已请求打开PotPlayer，请选择媒体。";await RefreshSources();}catch(Exception e){status.Text=e.Message;}};
        var file=new BarcaButton{Text="选择媒体文件…",Bounds=new(195,342,185,32)};file.Click+=async(_,_)=>{if(preview)return;using var picker=new OpenFileDialog{Title="用PotPlayer打开媒体",Filter="媒体文件|*.mp4;*.mkv;*.avi;*.mov;*.mp3;*.flac;*.wav;*.m3u;*.m3u8|所有文件|*.*"};if(picker.ShowDialog(this)==DialogResult.OK)try{MediaControl.OpenPotPlayer(picker.FileName);await RefreshSources();}catch(Exception e){status.Text=e.Message;}};
        var refresh=new BarcaButton{Text="刷新",Bounds=new(460,342,116,32)};refresh.Click+=async(_,_)=>await RefreshSources();status.SetBounds(24,386,552,35);status.ForeColor=BarcaUi.Muted;status.Font=BarcaUi.Font(8.5f);Controls.AddRange([sources,title,detail,buttons,open,file,refresh,status,chrome]);MinimumSize=MaximumSize=Size;Shown+=async(_,_)=>{await RefreshSources();timer.Start();};timer.Tick+=async(_,_)=>{if(Visible&&!busy)await RefreshSources();};
    }
    async Task RefreshSources(){if(refreshing||IsDisposed)return;refreshing=true;try{var rows=preview?new[]{new MediaSession("potplayer:preview","PotPlayer","示例视频","","Unknown")}:await MediaControl.SessionsAsync(life.Token);if(IsDisposed)return;string selected=(sources.SelectedItem as MediaSession)?.Id??MediaControl.Service.SelectedId;sources.BeginUpdate();sources.Items.Clear();sources.Items.AddRange(rows);sources.SelectedItem=rows.FirstOrDefault(s=>s.Id==selected)??rows.FirstOrDefault(s=>s.Status=="Playing")??rows.FirstOrDefault();sources.EndUpdate();if(rows.Length==0){title.Text="尚无可控制的播放器";detail.Text="先打开PotPlayer选择视频，或在QQ音乐播放歌曲。";if(MediaControl.Service.LastError!=null)status.Text="Windows媒体接口："+MediaControl.Service.LastError;}else if(status.Text.Length==0)status.Text="已连接本机媒体接口 · 不调用模型 API";}catch(OperationCanceledException){}catch(Exception e){if(!IsDisposed)status.Text=e.Message+" · 可点击刷新重试";}finally{refreshing=false;}}
    protected override void Dispose(bool disposing){if(disposing&&!closed){closed=true;timer.Stop();timer.Dispose();life.Cancel();life.Dispose();}base.Dispose(disposing);}
}
sealed partial class PetForm
{
    MediaForm? mediaWindow;
    void ShowMedia(){Modules.Require(prefs,"media");if(mediaWindow==null||mediaWindow.IsDisposed)mediaWindow=new MediaForm((a,v,t)=>commands.ExecuteAsync(new(a,v,"media-ui"),t),previewMode);if(!mediaWindow.Visible)WindowPositions.Prepare(mediaWindow,"media",Bounds,previewMode);WindowInteraction.Show(mediaWindow);}
}
